goto_if_set FLAG_ITEM_ROUTE_102_POTION Route102_EventScript_ItemPotion_Taken
finditem ITEM_POTION
setflag FLAG_ITEM_ROUTE_102_POTION
end
= Route102_EventScript_ItemPotion_Taken
end
